  const labels = kinds.filter(([, set]) => names.some(n => set.includes(n))).map(([label]) => label);
  const short = labels.length === 1 ? labels[0] : labels.length ? labels.slice(0, 2).join('、') : calls.length ? ui('执行操作') : step.reply ? ui('整理回复') : ui('暂无动作记录');
